class Solution{int i;NestedInteger f(String s){if(s.charAt(i)!='['){int sign=1,v=0;if(s.charAt(i)=='-'){sign=-1;i++;}while(i<s.length()&&Character.isDigit(s.charAt(i)))v=v*10+s.charAt(i++)-'0';return new NestedInteger(sign*v);}NestedInteger r=new NestedInteger();i++;while(s.charAt(i)!=']'){r.add(f(s));if(s.charAt(i)==',')i++;}i++;return r;}public NestedInteger deserialize(String s){i=0;return f(s);}}
